using System.Net;
using System.Text;
using System.Text.Json;
using PaymentAuthorization.Domain;
using PaymentAuthorization.Infrastructure;

namespace PaymentAuthorization.IntegrationTest.PaymentGateway;

public sealed class HttpPaymentGatewayTests : IDisposable
{
    private readonly HttpListener listener = new();
    private readonly HttpClient client;
    private readonly string baseUrl;
    private Task<Captured>? pending;

    private sealed record Captured(string Method, string Path, string? ContentType, string Body);

    public HttpPaymentGatewayTests()
    {
        var port = GetFreePort();
        baseUrl = $"http://127.0.0.1:{port}/";
        listener.Prefixes.Add(baseUrl);
        listener.Start();
        client = new HttpClient { BaseAddress = new Uri(baseUrl) };
    }

    private void Respond(int status, string body)
    {
        pending = Task.Run(async () =>
        {
            var ctx = await listener.GetContextAsync();
            using var reader = new StreamReader(ctx.Request.InputStream, Encoding.UTF8);
            var captured = new Captured(ctx.Request.HttpMethod, ctx.Request.Url!.AbsolutePath,
                ctx.Request.ContentType, await reader.ReadToEndAsync());
            var bytes = Encoding.UTF8.GetBytes(body);
            ctx.Response.StatusCode = status;
            ctx.Response.ContentType = "application/json";
            await ctx.Response.OutputStream.WriteAsync(bytes);
            ctx.Response.Close();
            return captured;
        });
    }

    private Task<AuthorizationOutcome> Authorize() =>
        new HttpPaymentGateway(client).AuthorizeAsync("ORD-7", new Money(12.5m, "eur"), CancellationToken.None);

    [Fact]
    public async Task Sends_a_json_post_to_the_authorizations_endpoint_with_reference_amount_and_currency()
    {
        Respond(200, """{"status":"approved"}""");

        await Authorize();

        var sent = await pending!;
        Assert.Equal("POST", sent.Method);
        Assert.Equal("/v1/authorizations", sent.Path);
        Assert.StartsWith("application/json", sent.ContentType);
        using var json = JsonDocument.Parse(sent.Body);
        var root = json.RootElement;
        Assert.Equal(3, root.EnumerateObject().Count());
        Assert.Equal("ORD-7", root.GetProperty("reference").GetString());
        Assert.Equal(12.5m, root.GetProperty("amount").GetDecimal());
        Assert.Equal("EUR", root.GetProperty("currency").GetString());
    }

    [Fact]
    public async Task An_approved_status_is_read_as_approved()
    {
        Respond(200, """{"status":"approved"}""");
        Assert.Equal(AuthorizationOutcome.Approved, await Authorize());
    }

    [Fact]
    public async Task A_declined_status_is_read_as_declined()
    {
        Respond(200, """{"status":"declined"}""");
        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Fact]
    public async Task An_unrecognised_status_is_never_treated_as_approved()
    {
        Respond(200, """{"status":"pending"}""");
        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Fact]
    public async Task A_response_without_a_status_is_never_treated_as_approved()
    {
        Respond(200, """{"decision":"approved"}""");
        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Fact]
    public async Task A_402_refusal_is_a_decline_not_an_error()
    {
        Respond(402, """{"error":"card_refused"}""");
        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Theory]
    [InlineData(400)]
    [InlineData(401)]
    [InlineData(422)]
    [InlineData(500)]
    [InlineData(503)]
    public async Task Other_error_statuses_surface_as_failures_rather_than_decisions(int status)
    {
        Respond(status, """{"status":"approved"}""");
        var ex = await Assert.ThrowsAsync<HttpRequestException>(Authorize);
        Assert.Equal((HttpStatusCode)status, ex.StatusCode);
    }

    [Fact]
    public async Task A_malformed_body_surfaces_as_a_failure()
    {
        Respond(200, "not json");
        await Assert.ThrowsAsync<JsonException>(Authorize);
    }

    public void Dispose()
    {
        client.Dispose();
        listener.Close();
    }

    private static int GetFreePort()
    {
        var probe = new System.Net.Sockets.TcpListener(IPAddress.Loopback, 0);
        probe.Start();
        var port = ((IPEndPoint)probe.LocalEndpoint).Port;
        probe.Stop();
        return port;
    }
}
